CREATE OR ALTER VIEW dbo.vw_ai_dashboard_events_unified_v2 AS
SELECT event_id,machine_id,CAST(NULL AS DATETIME2) source_event_start_time,CAST(NULL AS DATETIME2) source_event_end_time,CAST(NULL AS DATETIME2) scored_time,status_id,status_type_code,current_signal_code,risk_fault_10_events,risk_fault_30_events,risk_fault_30min,risk_fault_60min,risk_maintenance_30_events,risk_repair_30_events,operational_action_level,operational_judgment,operational_overall_risk_score,quality_action_level,quality_judgment,quality_risk_score,is_behavior_anomaly,is_sensitive_warning,l2_run_id,policy_version,CAST('historical' AS NVARCHAR(20)) data_source
FROM dbo.ai_l2_fault_judgment_policy_v2_full
UNION ALL
SELECT event_id,machine_id,source_event_start_time,source_event_end_time,scored_time,status_id,status_type_code,current_signal_code,risk_fault_10_events,risk_fault_30_events,risk_fault_30min,risk_fault_60min,risk_maintenance_30_events,risk_repair_30_events,operational_action_level,operational_judgment,operational_overall_risk_score,quality_action_level,quality_judgment,quality_risk_score,is_behavior_anomaly,is_sensitive_warning,l2_run_id,policy_version,CAST('online' AS NVARCHAR(20)) data_source
FROM dbo.ai_l2_fault_judgment_online_v2;
GO
